theorem consumed_continues_transformed (dependent : W.Dependent) {T : Nat} {g : F} {c : C}
    (below : ∀ t, T < t → W.level t c < W.need T g c) {t : Nat} (later : T < t)
    (active : W.active t g) : ¬ (W.requires t g c ∧ W.need T g c ≤ W.need t g c)

def bear (onShapers onOthers : Nat) (g : CarrierCounts) : CarrierCounts :=
  ⟨g.carrier + onOthers, g.other + onShapers,
    Nat.lt_of_lt_of_le g.other_pos (Nat.le_add_right _ _)⟩

theorem kept_of_descent {G : Generations α} {Q : α → Prop}
    (keeps : ∀ t p k, p ∈ G.family t → k ∈ G.kids t p → Q p → Q k) (founders : ∀ x, x ∈ G.first → Q x) :
    ∀ t x, x ∈ G.family t → Q x

def SelectsThrough (W : Web F C) (obs : F → C → Prop) (f : F) (t : Nat)
    (select : (Nat → C → Nat) → Prop) : Prop :=
  ∀ l l', W.AlikeThroughUpTo obs f l l' t → (select l ↔ select l')

theorem varied_before (G : Generations α) {v : Nat}
    (founded : ∀ p, p ∈ G.family 0 → G.amount 0 p = v) {t : Nat}
    (selected : G.concordAt t ≠ 0 ∨ G.discordAt t ≠ 0) :
    ∃ s, s < t ∧ (0 < G.raisedAt s ∨ 0 < G.loweredAt s)
